module SNPS_CLOCK_GATE_HIGH_cordic_rotation_1_0 ( CLK, EN, ENCLK );
  input CLK, EN;
  output ENCLK;
  wire   net2414, net2416, net2417, net2420;
  assign net2414 = CLK;
  assign ENCLK = net2416;
  assign net2417 = EN;

  QDBHN latch ( .CKB(net2414), .D(net2417), .Q(net2420) );
  AN2 main_gate ( .I1(net2420), .I2(net2414), .O(net2416) );
endmodule


